class Solution {
    public int[] pickTwo(int[] prices, int budget) {
        int n = prices.length;
        Integer[] order = new Integer[n];
        for (int k = 0; k < n; k++) order[k] = k;
        Arrays.sort(order, (a, b) -> Integer.compare(prices[a], prices[b]));
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            long total = (long) prices[order[lo]] + prices[order[hi]];
            if (total == budget) {
                int a = order[lo], b = order[hi];
                return new int[] {Math.min(a, b), Math.max(a, b)};
            }
            if (total > budget) hi--;
            else lo++;
        }
        return new int[0];
    }
}

