static int* gPrices;

static int byPrice(const void* x, const void* y) {
    int a = gPrices[*(const int*) x], b = gPrices[*(const int*) y];
    return (a > b) - (a < b);
}

int* pickTwo(int* prices, int pricesSize, int budget, int* returnSize) {
    int* order = malloc(pricesSize * sizeof(int));
    for (int k = 0; k < pricesSize; k++) order[k] = k;
    gPrices = prices;
    qsort(order, pricesSize, sizeof(int), byPrice);
    int* answer = malloc(2 * sizeof(int));
    *returnSize = 0;
    int lo = 0, hi = pricesSize - 1;
    while (lo < hi) {
        long long total = (long long) prices[order[lo]] + prices[order[hi]];
        if (total == budget) {
            int a = order[lo], b = order[hi];
            answer[0] = a < b ? a : b;
            answer[1] = a < b ? b : a;
            *returnSize = 2;
            break;
        }
        if (total > budget) hi--;
        else lo++;
    }
    free(order);
    return answer;
}

