class Solution {
    public int[] pickTwo(int[] prices, int budget) {
        Map<Long, Integer> where = new HashMap<>();
        for (int j = 0; j < prices.length; j++) {
            long need = (long) budget - prices[j];
            Integer i = where.get(need);
            if (i != null) return new int[] {i, j};
            where.put((long) prices[j], j);
        }
        return new int[0];
    }
}

