class Solution {
public:
    vector<int> pickTwo(vector<int>& prices, int budget) {
        unordered_map<long long, int> where;
        where.reserve(prices.size() * 2);
        for (int j = 0; j < (int) prices.size(); j++) {
            long long need = (long long) budget - prices[j];
            auto it = where.find(need);
            if (it != where.end()) return {it->second, j};
            where[prices[j]] = j;
        }
        return {};
    }
};

