// C has no built-in hash map, so here is a small one: open addressing
// with linear probing. Keys are prices, values are indices.
typedef struct { long long key; int val; bool used; } Slot;

static unsigned slotOf(long long key, unsigned mask) {
    unsigned long long h = (unsigned long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

int* pickTwo(int* prices, int pricesSize, int budget, int* returnSize) {
    unsigned cap = 1;
    while (cap < 2u * pricesSize) cap <<= 1;
    Slot* where = calloc(cap, sizeof(Slot));
    int* answer = malloc(2 * sizeof(int));
    *returnSize = 0;
    for (int j = 0; j < pricesSize; j++) {
        long long need = (long long) budget - prices[j];
        unsigned s = slotOf(need, cap - 1);
        while (where[s].used && where[s].key != need) s = (s + 1) & (cap - 1);
        if (where[s].used) {
            answer[0] = where[s].val;
            answer[1] = j;
            *returnSize = 2;
            break;
        }
        s = slotOf(prices[j], cap - 1);
        while (where[s].used && where[s].key != prices[j]) s = (s + 1) & (cap - 1);
        where[s] = (Slot) {prices[j], j, true};
    }
    free(where);
    return answer;
}
